import{_ as s}from"./chunks/entity-picker.BuWRM8I6.js";import{_ as t,o as n,c as i,a3 as a}from"./chunks/framework.BlfGB29P.js";const f=JSON.parse('{"title":"Entités Home Assistant","description":"","frontmatter":{"title":"Entités Home Assistant"},"headers":[],"relativePath":"fr/projects/blocks-for-ha/entities.md","filePath":"fr/projects/blocks-for-ha/entities.md","lastUpdated":1793126212000}'),o={name:"fr/projects/blocks-for-ha/entities.md"};function r(l,e,c,d,u,p){return n(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="entites-home-assistant" tabindex="-1">Entités Home Assistant <a class="header-anchor" href="#entites-home-assistant" aria-label="Permalink to &quot;Entités Home Assistant&quot;">​</a></h1><p>Depuis <strong>0.1.44</strong>, les champs appropriés des blocs simples et avancés ouvrent une sélection avec recherche. Une petite flèche les signale. <strong>HA-Auswahl laden</strong> et <strong>Neu laden</strong> actualisent les catalogues en lecture seule. Les actions viennent de HA ; les cibles suivent <code>entity_id</code>, <code>device_id</code>, <code>area_id</code>, <code>floor_id</code> ou <code>label_id</code> : entités, appareils, zones, étages ou étiquettes. Les quatre derniers catalogues ne sont pas filtrés par action.</p><p><strong>Mehrere Ziele auswählen</strong> permet plusieurs cibles dans les champs prenant en charge les listes. IDs manuels, listes JSON et modèles Jinja pris en charge restent disponibles, y compris le texte multiligne intégral. Changer le type de cible ne réécrit pas les IDs existants. Sans catalogue d’actions, les exemples courants sont explicitement signalés ; les catalogues indisponibles permettent la saisie manuelle. Les menus spécialisés sont conservés. Noms de variables, IDs de déclencheurs, attributs, texte libre et données complexes ne reçoivent pas de sélection HA générique.</p><p>Installer <strong>0.1.44</strong> puis redémarrer l’application. Le serveur lit les entités et actions via l’<a href="https://developers.home-assistant.io/docs/api/rest/" target="_blank" rel="noreferrer">API REST</a> et les registres de cibles via l’<a href="https://developers.home-assistant.io/docs/api/websocket/" target="_blank" rel="noreferrer">API WebSocket</a>. Les permissions manquantes affectent seulement la liste concernée. Aucun jeton HA n’est envoyé au navigateur. La connexion et le nombre d’entités apparaissent dans la barre des réglages.</p><p>Cliquer sur un champ d’entité d’un bloc ouvre le sélecteur. Chercher par nom ou ID puis choisir une ligne. Les noms affichés viennent de votre installation et ne sont pas traduits. Les mots de recherche peuvent correspondre au nom ou à l’ID. Le choix remplit le champ actuellement modifié.</p><p>Le filtre suit le type du bloc : une lampe pour une action de couleur, un script pour un appel de script, le domaine approprié pour un assistant. Les actions génériques peuvent avoir une cible vide si leur service le permet. Les autres IDs doivent respecter <code>domaine.identifiant</code>.</p><p>La saisie manuelle reste possible, y compris hors HA. En cas de connexion indisponible, aucun état d’entité simulé n’est présenté comme une connexion réelle. Le chargement est une lecture : il n’exécute pas l’automatisation et n’écrit pas dans HA.</p><p>Les blocs standard avec sélecteur d’entité et les paquets personnalisés déclarant un champ <code>entity</code> utilisent ce mécanisme. La liste contient uniquement les informations publiques utiles à l’éditeur, sans attributs arbitraires ou jetons. Ne pas coller de secrets dans les champs de données ou projets.</p><p>Installer une fois la dépendance avec <code>python -m pip install --require-hashes -r requirements.txt</code>, puis lancer le service local avec <code>npm run entities</code>. Docker installe automatiquement la dépendance. Les 163 types de blocs, filtres, cinq types de cibles, listes et Jinja sont vérifiés automatiquement. Les tests serveur utilisent des réponses HA simulées ; vérifier ensuite l’exécution dans Home Assistant.</p><p><a href="./blocks">Catalogue des blocs</a> · <a href="https://developers.home-assistant.io/docs/add-ons/presentation/#ingress" target="_blank" rel="noreferrer">Documentation Ingress HA</a>.</p><details class="details custom-block"><summary>Référence détaillée issue de la documentation allemande</summary><h2 id="entitaten-auswahlen" tabindex="-1">Sélectionner des entités <a class="header-anchor" href="#entitaten-auswahlen" aria-label="Permalink to &quot;Sélectionner des entités {#entitaten-auswahlen}&quot;">​</a></h2><p>Depuis la version <strong>0.1.44</strong>, les champs d&#39;action et de cible appropriés, présents dans les blocs simples et avancés, ouvrent une interface de sélection avec fonction de recherche. Une petite flèche indique ces champs. Les options <strong>Charger la sélection HA</strong> (dans la barre d&#39;outils) et <strong>Recharger</strong> (dans la boîte de dialogue) permettent de mettre à jour les catalogues disponibles.</p><p><img src="'+s+'" alt="Sélection d&#39;entités avec résultat de recherche"></p><p>L&#39;image utilise des entités de test simulées et l&#39;interface en allemand. Depuis la version 0.1.46, l&#39;interface s&#39;adapte à la langue choisie pour l&#39;application (DE/EN/FR). Les noms des entités sont repris tels quels depuis votre installation HA.</p><h3 id="bedienung" tabindex="-1">Utilisation <a class="header-anchor" href="#bedienung" aria-label="Permalink to &quot;Utilisation {#bedienung}&quot;">​</a></h3><ol><li>Cliquez sur l&#39;identifiant (ID) de l&#39;entité au sein du bloc.</li><li>Effectuez une recherche par nom ou par identifiant. Si vous utilisez plusieurs termes de recherche, ils doivent tous correspondre. Les 150 premiers résultats sont affichés ; affinez votre recherche si la liste est trop longue.</li><li>Sélectionnez un résultat et cliquez sur <strong>Appliquer</strong>. Le bloc ne sera mis à jour qu&#39;après cette action. Si vous cliquez sur <strong>Annuler</strong> ou appuyez sur la touche Échap, le bloc restera inchangé.</li><li>Vous pouvez également saisir directement un identifiant (par exemple <code>light.wohnzimmer</code>). Cette méthode fonctionne même hors ligne ou pour des entités qui n&#39;ont pas encore été chargées.</li></ol><p>La liste affiche le nom, l&#39;identifiant et l&#39;état actuel (y compris l&#39;unité de mesure). Ces états constituent un <strong>instantané</strong> ; ils ne permettent pas un suivi en continu et ne servent pas de blocs de valeurs de capteurs pour des scénarios d&#39;automatisation.</p><table tabindex="0"><thead><tr><th>Bloc</th><th>Sélection</th></tr></thead><tbody><tr><td>Déclencheurs et conditions basés sur un état ou une valeur numérique</td><td>Toutes les entités chargées</td></tr><tr><td>Éclairages (avec couleur/luminosité)</td><td>Uniquement <code>light</code></td></tr><tr><td>Script HA (Home Assistant)</td><td>Uniquement <code>script</code></td></tr><tr><td>Assistants (Helpers)</td><td>Selon le type sélectionné : <code>input_boolean</code>, <code>counter</code> ou <code>timer</code></td></tr><tr><td>Activer/désactiver/basculer, mettre à jour une entité, action HA générique</td><td>Toutes les entités chargées ; veuillez vérifier si l&#39;action spécifique est prise en charge par HA</td></tr></tbody></table><p>Les champs d&#39;action affichent les actions signalées par Home Assistant (HA). Les entités cibles sont filtrées en fonction des domaines spécifiés dans la description ou le nom de l&#39;action. La sélection de la cible suit les catégories <code>entity_id</code>, <code>device_id</code>, <code>area_id</code>, <code>floor_id</code> ou <code>label_id</code> : entités, appareils, zones, étages ou étiquettes. Les quatre derniers catalogues ne sont pas filtrés en fonction de l&#39;action. La <strong>sélection de plusieurs cibles</strong> permet d&#39;obtenir des listes dans les champs compatibles. Les identifiants personnalisés, les listes JSON et les modèles Jinja pris en charge restent disponibles ; le texte Jinja multiligne est conservé dans son intégralité. La modification du type de cible n&#39;entraîne pas la réécriture des identifiants existants.</p><p>Les scènes et les assistants (« helpers ») proposent des domaines d&#39;entités pertinents ; les limites numériques étendues incluent également les capteurs et les assistants numériques, tandis que les champs liés au temps englobent les assistants temporels et les capteurs. La saisie manuelle de nombres ou de durées reste possible. Les menus déroulants spécialisés sont conservés. Les noms de variables, les identifiants de déclenchement (« trigger IDs »), les attributs, les champs de texte libre et les données complexes ne sont pas soumis aux menus de sélection génériques de Home Assistant (HA). La modification d&#39;un identifiant ne met pas à jour les références présentes dans les données Jinja ou JSON saisies manuellement. En l&#39;absence de catalogue d&#39;actions, des exemples courants — explicitement identifiés comme tels — sont affichés ; si aucun catalogue de cibles n&#39;est disponible, la saisie manuelle d&#39;identifiants est autorisée.</p><h3 id="ha-app-und-daten" tabindex="-1">Application et données HA <a class="header-anchor" href="#ha-app-und-daten" aria-label="Permalink to &quot;Application et données HA {#ha-app-und-daten}&quot;">​</a></h3><p>Mettez à jour le dépôt dans le HA App Store, installez la <strong>version 0.1.44</strong> et redémarrez l&#39;application. L&#39;application nécessite <code>homeassistant_api: true</code> et utilise <code>SUPERVISOR_TOKEN</code> côté serveur. Les entités et les actions sont récupérées via l&#39; <a href="https://developers.home-assistant.io/docs/api/rest/" target="_blank" rel="noreferrer">API REST</a>, tandis que les enregistrements de cibles sont accessibles via l&#39; <a href="https://developers.home-assistant.io/docs/api/websocket/" target="_blank" rel="noreferrer">API WebSocket</a>. L&#39;absence d&#39;autorisations dans le registre n&#39;affecte que la liste spécifique concernée. Aucune saisie de jeton (« token ») n&#39;est requise dans l&#39;éditeur.</p><p>Le navigateur ne reçoit que des métadonnées sélectives : ID, nom d&#39;affichage, domaines et, pour les entités, l&#39;état et l&#39;unité. Aucun autre attribut ni identifiant d&#39;accès n&#39;est transmis. Les points de terminaison se limitent à la lecture des catalogues et n&#39;exécutent aucune action HA (Home Assistant). Le serveur ne suit pas les redirections impliquant des identifiants d&#39;accès.</p><p>La liste est issue de la liste des états de HA, et non de l&#39;ensemble du registre des entités. Les entités désactivées ou celles qui ne sont pas encore disponibles (et n&#39;ont donc pas d&#39;état) peuvent être absentes. <code>unknown</code>/<code>unavailable</code> sont affichés s&#39;ils sont présents dans la liste. En cas d&#39;erreur de chargement, la liste précédente est écartée ; les ID de bloc existants sont toutefois conservés.</p><p>Les valeurs de champ sélectionnées sont stockées dans le projet JSON et dans le fichier YAML. Le catalogue, les noms, l&#39;aperçu des états et les identifiants d&#39;accès ne sont ni enregistrés ni exportés. L&#39;ensemble des 163 types de blocs est conservé. Avant toute mise à jour, téléchargez votre projet local via l&#39;option <strong>Sauvegarder le projet</strong> ; une sauvegarde du code source ne contient pas la session du navigateur.</p><h3 id="lokale-entwicklung" tabindex="-1">Développement local <a class="header-anchor" href="#lokale-entwicklung" aria-label="Permalink to &quot;Développement local {#lokale-entwicklung}&quot;">​</a></h3><p>La dépendance Python doit être installée une fois via <code>python -m pip install --require-hashes -r requirements.txt</code>. Avec Docker, cette installation est automatique.</p><p><code>npm run dev</code> fonctionne seul avec des ID définis manuellement. Pour établir une connexion, lancez également Python 3 : <code>npm run entities</code>. Définissez les variables d&#39;environnement <code>BLOCKS_HA_URL</code> (adresse de base sans <code>/api</code>, par exemple <code>http://homeassistant.local:8123</code>) et <code>BLOCKS_HA_TOKEN</code> uniquement au niveau du processus serveur. Le serveur Vite, situé sur <code>127.0.0.1:4180</code>, transmet la requête au pont local (bridge) sur <code>127.0.0.1:9001</code>. Ne saisissez jamais d&#39;identifiants d&#39;accès dans le code source ou dans les fichiers du projet.</p><p>La version Docker lance simultanément le pont (bridge) et l&#39;interface web. En dehors de HA, si des identifiants sont définis, il convient de restreindre l&#39;accès à une liaison locale uniquement ou d&#39;utiliser une interface intermédiaire authentifiée ; un système de connexion utilisateur autonome n&#39;est pas encore implémenté. Au sein de HA, l&#39;accès est protégé par Ingress.</p><h3 id="prufung" tabindex="-1">Tests <a class="header-anchor" href="#prufung" aria-label="Permalink to &quot;Tests {#prufung}&quot;">​</a></h3><p>La compatibilité avec les projets/fichiers YAML, les fonctions de recherche et de filtrage, l&#39;annulation, la saisie manuelle, la gestion des erreurs, l&#39;affichage sur mobile ainsi que l&#39;ensemble de la chaîne Docker ont été vérifiés face à un serveur HA simulé. Un test pratique dans une installation HA réelle reste à effectuer. La sélection d&#39;une entité ne garantit pas que l&#39;appareil choisi prend effectivement en charge l&#39;action sélectionnée.</p></details>',11)])])}const g=t(o,[["render",r]]);export{f as __pageData,g as default};
